TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs, unsigned long attr_count) {
    TEE_Result result = TEE_SUCCESS;
    struct crypto_session *session;
    struct crypto_object *crypto_obj;
    struct utee_attribute *attrs = NULL;

    session = get_current_session();
    if (!session)
        return TEE_ERROR_BAD_SESSION;

    crypto_obj = find_object_by_id(session, obj);
    if (!crypto_obj || !is_transient_uninitialized(crypto_obj))
        return TEE_ERROR_BAD_PARAMETERS;

    attrs = calloc(attr_count, sizeof(struct utee_attribute));
    if (!attrs)
        return TEE_ERROR_OUT_OF_MEMORY;

    if (copy_from_user(attrs, usr_attrs, attr_count * sizeof(struct utee_attribute)) != 0) {
        result = TEE_ERROR_BAD_PARAMETERS;
        goto cleanup;
    }

    if (!validate_attributes(crypto_obj->type, attrs, attr_count)) {
        result = TEE_ERROR_INVALID_ARGUMENT;
        goto cleanup;
    }

    crypto_obj->attributes = attrs;
    crypto_obj->attribute_count = attr_count;
    crypto_obj->state = OBJ_STATE_INITIALIZED;

cleanup:
    if (result != TEE_SUCCESS) {
        free(attrs);
    }

    return result;
}

