TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs, unsigned long attr_count) {
    TEE_Result res = TEE_ERROR_GENERIC;
    struct tee_session *session = tee_get_current_session();
    struct tee_object *object;

    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    object = tee_get_object_by_id(obj);
    if (!object || !object->is_transient || object->is_initialized) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    object->attributes = calloc(attr_count, sizeof(struct tee_attribute));
    if (!object->attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    for (unsigned long i = 0; i < attr_count; i++) {
        if (tee_copy_from_user(&object->attributes[i], &usr_attrs[i], sizeof(struct utee_attribute))) {
            res = TEE_ERROR_BAD_PARAMETERS;
            goto cleanup;
        }
    }

    res = validate_attributes_against_object(object);
    if (res != TEE_SUCCESS) {
        goto cleanup;
    }

    object->is_initialized = 1;
    res = TEE_SUCCESS;

cleanup:
    if (res != TEE_SUCCESS) {
        free(object->attributes);
        object->attributes = NULL;
    }

    return res;
}

TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs, unsigned long attr_count) {
    TEE_Result res = TEE_ERROR_GENERIC;
    struct tee_session *session = tee_get_current_session();
    struct tee_object *object;

    if (!session)
        return TEE_ERROR_BAD_STATE;

    object = tee_get_object_by_id(session, obj);
    if (!object || !object->is_transient || object->is_initialized)
        return TEE_ERROR_BAD_PARAMETERS;

    object->attributes = malloc(attr_count * sizeof(struct tee_attribute));
    if (!object->attributes)
        return TEE_ERROR_OUT_OF_MEMORY;

    for (unsigned long i = 0; i < attr_count; i++) {
        struct utee_attribute *usr_attr = &usr_attrs[i];
        struct tee_attribute *attr = &object->attributes[i];

        attr->type = usr_attr->type;
        attr->value = malloc(usr_attr->value_size);
        if (!attr->value) {
            res = TEE_ERROR_OUT_OF_MEMORY;
            break;
        }
        memcpy(attr->value, usr_attr->value, usr_attr->value_size);
        attr->size = usr_attr->value_size;
    }

    if (res != TEE_SUCCESS)
        goto error_cleanup;

    res = validate_attributes(object, attr_count);
    if (res != TEE_SUCCESS)
        goto error_cleanup;

    object->is_initialized = 1;

    return TEE_SUCCESS;

error_cleanup:
    for (unsigned long i = 0; i < attr_count; i++) {
        struct tee_attribute *attr = &object->attributes[i];
        free(attr->value);
    }
    free(object->attributes);
    object->attributes = NULL;
    return res;
}

TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs, unsigned long attr_count) {
    TEE_Result res = TEE_SUCCESS;
    struct tee_session *session = tee_get_current_session();
    struct tee_object *object = tee_get_object_by_id(obj);

    if (!session || !object) {
        return TEE_ERROR_ITEM_NOT_FOUND;
    }

    if (!object->is_transient || object->is_initialized) {
        return TEE_ERROR_BAD_STATE;
    }

    struct utee_attribute *attrs = calloc(attr_count, sizeof(*attrs));
    if (!attrs) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    if (tee_copy_from_user(attrs, usr_attrs, attr_count * sizeof(*attrs)) != 0) {
        free(attrs);
        return TEE_ERROR_BAD_PARAMETERS;
    }

    for (unsigned long i = 0; i < attr_count; i++) {
        if (tee_validate_attribute(object, &attrs[i]) != TEE_SUCCESS) {
            free(attrs);
            return TEE_ERROR_BAD_PARAMETERS;
        }
    }

    res = tee_populate_object(object, attrs, attr_count);
    if (res == TEE_SUCCESS) {
        object->is_initialized = 1;
    }

    free(attrs);
    return res;
}
